"""Derive SkyyRebirth/build_skyyrebirth_0.3.3.py from SkyyRebirth/build_skyyrebirth_0.3.2.py (= the tools/deploy_set.py SET pin, GENERATED by
tools/rebirth_0_3_2_patch.py). rep(old, new) with asserted anchors; 0.3.2 stays untouched; its line endings are kept; every change is checked
at the end to prove nothing else changed.
Run:  python tools/rebirth_0_3_3_patch.py   then   python SkyyRebirth/build_skyyrebirth_0.3.3.py   (NO --deploy: coordinated deploy)
Test: python SkyyRebirth/test_skyyrebirth_0.3.3.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all)

0.3.3 (2026-10-14) = REBIRTH WRAP-UP, the SkyyRebirth part (Skyy 2026-10-14 ~18:30, picking "7. Rebirth wrap-up: ... mods start using
the tree's stat nodes" from the main session's list: "do 1. 3. 6. 7. 8. and 9."). Texts + ONE code line - no saved data, no bridge
key changes (rebirth:fn:stat answers as in 0.3.2: "all" = min(stat.cap, stat.perRebirth x n) + the Void Ascendant, "health" / "damage" /
"defense" / "mana" / "classxp" = the Class arm's nodes), EXCEPT (fix round): a profile whose file could not be read (RbStore.BAD - it
counts as 0 rebirths and is never overwritten) answers rebirth:fn:stat with NO answer (null) instead of 0, so the stat mods keep the
player's last / saved stat boosts instead of dropping them on a read error (Avast lock). Every other mode answers as before.
SkyySkills 0.4.39 now APPLIES the stats it owns:
  - max Health = all + health (Vitality, Greater Vitality), max Mana = all + mana (Focus, Greater Focus), max Stamina = all,
    class XP = classxp (Class Wisdom). Damage (Might) and defense (Guard) wait for SkyyGear (the gear6 round reads rebirth:fn:stat
    "damage" / "defense" + "all").
  The node panel's "Works" lines say so: Vitality / Greater Vitality "now (SkyySkills: max Health)", Focus / Greater Focus "now
  (SkyySkills: max Mana)", Class Wisdom "now (SkyySkills: class XP)", Might / Guard "when SkyyGear applies rebirth damage / defense",
  Void Ascendant "now (title; Health, Mana, Stamina); damage / defense later". Server Setup helps of stat.perRebirth, tree.statNode and
  tree.keyStat name what applies them. The Swift Brewing / Smithing / Cooking nodes are CRAFTING speed (not move speed) - still "a
  later update" (no mod has a bench-speed pipeline yet).
  ROLLBACK to 0.3.2: safe (texts + the read-error answer only).
"""
import difflib
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.3.2.py")
dst = os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.3.3.py")
raw = open(src, "rb").read()
NL = "\r\n" if b"\r\n" in raw else "\n"
assert NL == "\n" or raw.count(b"\r\n") == raw.count(b"\n"), "mixed line endings in 0.3.2"
s = raw.decode("utf8").replace("\r\n", "\n")
LF = "\n"
S0 = s
assert 'VERSION = "0.3.2"' in s and "GENERATED by tools/rebirth_0_3_2_patch.py" in s and '"gear" };' in s, "not the generated 0.3.2"
OLDS = []


def rep(old, new, count=1):
    global s
    n = s.count(old)
    assert n == count, "anchor count %d (want %d): %s" % (n, count, old[:160])
    s = s.replace(old, new)
    OLDS.append(old)


HEAD = open(__file__, encoding="utf8").read().split('"""')[1]
NOTE = HEAD[HEAD.index("0.3.3 (2026-10-14)"):].rstrip() + "\n"

# ---------------------------------------------------------------- docstring + version
rep('''"""SkyyRebirth 0.3.2 - build script (javassist via jpype). GENERATED by tools/rebirth_0_3_2_patch.py from build_skyyrebirth_0.3.1.py (itself
generated by tools/rebirth_0_3_1_patch.py from 0.3, generated by tools/rebirth_0_3_patch.py from 0.2,''',
    '''"""SkyyRebirth 0.3.3 - build script (javassist via jpype). GENERATED by tools/rebirth_0_3_3_patch.py from build_skyyrebirth_0.3.2.py (itself
generated by tools/rebirth_0_3_2_patch.py from 0.3.1, generated by tools/rebirth_0_3_1_patch.py from 0.3, generated by tools/rebirth_0_3_patch.py
from 0.2,''')
rep('''Run:   python SkyyRebirth/build_skyyrebirth_0.3.2.py   -> SkyyRebirth/SkyyRebirth-0.3.2.jar   (no --deploy: tools/deploy_set.py installs the set)
Check: python SkyyRebirth/test_skyyrebirth_0.3.2.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every code path executed)
''', '''Run:   python SkyyRebirth/build_skyyrebirth_0.3.3.py   -> SkyyRebirth/SkyyRebirth-0.3.3.jar   (no --deploy: tools/deploy_set.py installs the set)
Check: python SkyyRebirth/test_skyyrebirth_0.3.3.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every code path executed)

''' + NOTE + '''  CHECKED: SkyyRebirth/test_skyyrebirth_0.3.3.py.
''')
rep('VERSION = "0.3.2"\n', 'VERSION = "0.3.3"\n')

# ---------------------------------------------------------------- the Class arm's "Works" lines (what applies each stat node now)
rep('''        _ls = "after a later update (stats)"
        tnode("Class.hp", "Vitality", 5, 0, 1, "+{v} % health", stat="health", live=_ls, cat=4)
        tnode("Class.dmg", "Might", 5, 0, 1, "+{v} % damage", stat="damage", live=_ls, cat=4)
        tnode("Class.def", "Guard", 5, 0, 1, "+{v} % defense", stat="defense", live=_ls, cat=4)
        tnode("Class.mana", "Focus", 5, 0, 1, "+{v} % mana", stat="mana", live=_ls, cat=4)
        tnode("Class.echo", "Echo", 5, 0, 4, "+{v} % Class rebirth points", bon="echo", live="now (your next rebirths)", cat=2)
        tnode("Class.xp", "Class Wisdom", 5, 0, 2, "+{v} % class XP", stat="classxp", live="after a later update (class XP)", cat=0)
        tnode("Class.hp2", "Greater Vitality", 5, 0, 1, "+{v} % health", stat="health", live=_ls, cat=4)
        tnode("Class.dmg2", "Greater Might", 5, 0, 1, "+{v} % damage", stat="damage", live=_ls, cat=4)
        tnode("Class.def2", "Greater Guard", 5, 0, 1, "+{v} % defense", stat="defense", live=_ls, cat=4)
        tnode("Class.mana2", "Greater Focus", 5, 0, 1, "+{v} % mana", stat="mana", live=_ls, cat=4)
        tnode("Class.key", "Void Ascendant", 1, 3, 2, "+{v} % all stats and the title", stat="all",
              live="now (the title); stats after a later update", title="Void Ascendant", cat=5)''',
    '''        # 0.3.3: SkyySkills 0.4.39 applies health / mana / all (max Health, Mana, Stamina) + classxp; damage / defense wait for SkyyGear
        _lh, _lm = "now (SkyySkills: max Health)", "now (SkyySkills: max Mana)"
        _lg = lambda w: "when SkyyGear applies rebirth %s" % w
        tnode("Class.hp", "Vitality", 5, 0, 1, "+{v} % health", stat="health", live=_lh, cat=4)
        tnode("Class.dmg", "Might", 5, 0, 1, "+{v} % damage", stat="damage", live=_lg("damage"), cat=4)
        tnode("Class.def", "Guard", 5, 0, 1, "+{v} % defense", stat="defense", live=_lg("defense"), cat=4)
        tnode("Class.mana", "Focus", 5, 0, 1, "+{v} % mana", stat="mana", live=_lm, cat=4)
        tnode("Class.echo", "Echo", 5, 0, 4, "+{v} % Class rebirth points", bon="echo", live="now (your next rebirths)", cat=2)
        tnode("Class.xp", "Class Wisdom", 5, 0, 2, "+{v} % class XP", stat="classxp", live="now (SkyySkills: class XP)", cat=0)
        tnode("Class.hp2", "Greater Vitality", 5, 0, 1, "+{v} % health", stat="health", live=_lh, cat=4)
        tnode("Class.dmg2", "Greater Might", 5, 0, 1, "+{v} % damage", stat="damage", live=_lg("damage"), cat=4)
        tnode("Class.def2", "Greater Guard", 5, 0, 1, "+{v} % defense", stat="defense", live=_lg("defense"), cat=4)
        tnode("Class.mana2", "Greater Focus", 5, 0, 1, "+{v} % mana", stat="mana", live=_lm, cat=4)
        tnode("Class.key", "Void Ascendant", 1, 3, 2, "+{v} % all stats and the title", stat="all",
              live="now (title; Health, Mana, Stamina); damage / defense later", title="Void Ascendant", cat=5)''')

# ---------------------------------------------------------------- Server Setup helps (<= 100 characters, the kit checks)
rep('''     "All stats +this % per rebirth (Skyy: 3), for the mods that apply stats.", "field:RbCfg.STAT_PER@config.properties:stat.perRebirth"),''',
    '''     "All stats +this % per rebirth (Skyy: 3): SkyySkills max Health / Mana / Stamina now.", "field:RbCfg.STAT_PER@config.properties:stat.perRebirth"),''')
rep('''     "Each Vitality / Might / Guard / Focus level: this % (for the mods that apply stats).", "field:RbCfg.W_STAT@config.properties:tree.statNode"),''',
    '''     "Each Vitality / Might / Guard / Focus level: this %. Health + Mana now, damage + defense later.", "field:RbCfg.W_STAT@config.properties:tree.statNode"),''')
rep('''     "Void Ascendant adds this % to all stats (with its title).", "field:RbCfg.W_KSTAT@config.properties:tree.keyStat"),''',
    '''     "Void Ascendant adds this % to all stats (with its title): Health, Mana, Stamina now.", "field:RbCfg.W_KSTAT@config.properties:tree.keyStat"),''')

# ---------------------------------------------------------------- rebirth:fn:stat: an unreadable profile file = no answer (fix round)
rep('''    if (this.mode == 6) return Double.valueOf(@PKG@.RbTree.stat(@PKG@.RbStore.get(k), @PKG@.RbStore.n(k), s));   // 0.3 rebirth:fn:stat
''', '''    if (this.mode == 6 && @PKG@.RbStore.BAD.containsKey(k)) return null;   // 0.3.3: a file that could not be read = no answer (the stat mods keep the last values)
    if (this.mode == 6) return Double.valueOf(@PKG@.RbTree.stat(@PKG@.RbStore.get(k), @PKG@.RbStore.n(k), s));   // 0.3 rebirth:fn:stat
''')

# ---------------------------------------------------------------- manifest
rep('''Server Setup: Rebirth. Zero dependencies.", PKG + ".SkyyRebirthPlugin")''',
    '''0.3.3: SkyySkills 0.4.39+ applies the stat boosts to max Health, Mana and Stamina and Class Wisdom to class XP. Server Setup: Rebirth. Zero dependencies.", PKG + ".SkyyRebirthPlugin")''')

# ---------------------------------------------------------------- checks
assert s.count("after a later update (stats)") == 0 and s.count("_lh, _lm = \"now (SkyySkills: max Health)\"") == 1
_a, _b = S0.split(LF), s.split(LF)
_hunks = [op for op in difflib.SequenceMatcher(None, _a, _b, autojunk=False).get_opcodes() if op[0] != "equal"]
_gone = [(i, _a[i]) for op in _hunks for i in range(op[1], op[2])]
_allowed = set()
for _o in OLDS:
    _allowed.update(_o.split(LF))
_bad = [(i, ln) for i, ln in _gone if ln not in _allowed and not any(_o in ln for _o in OLDS if LF not in _o)]
assert not _bad, "0.3.2 lines changed outside the planned places: %r" % _bad[:5]
if os.path.exists(dst):
    os.remove(dst)
compile(s, dst, "exec")
open(dst, "wb").write(s.replace(LF, NL).encode("utf8"))
print("wrote", dst, len(s), "chars;", len(_hunks), "diff hunks vs 0.3.2,", len(_gone), "0.3.2 lines replaced;", len(OLDS), "anchors")
